export class STMUSARTs extends UARTs {
 constructor(r){super(r);const f4=r.board.cpu==='cortex-m4f',number=f4?6:3;if(r.chip==='stm32f103c6')return;const u={number,base:f4?0x40011400:0x40004800,sr:0xc0,dr:0,tdr:null,shift:null,high:true,readSR:false,epoch:0};const cpu={get cycles(){return r.count;},addClockEvent:(fn,delay)=>{this.events.push({at:r.count+delay,unit:number,fn});this.events.sort((a,b)=>a.at-b.at);}};u.receiver=new UARTReceiver(cpu,()=>this.readLine(u),()=>this.format(u),frame=>this.receive(u,frame));this.units.push(u);}
 clocked(u){if(u.number<=2)return super.clocked(u);return !!(this.r.regs.get(u.number===6?0x40023844:0x4002101c)&(1<<(u.number===6?5:18)));}
 divider(u){return u.number===6?(this.r.system?.busDivider(2)??1)*(this.r.system?.factor()??1):super.divider(u);}
 normalPins(u){if(u.number===3){const map=((this.r.regs.get(0x40010004)||0)>>>4)&3;return map===3?{tx:'PD8',rx:'PD9'}:map===1?{tx:'PC10',rx:'PC11'}:{tx:'PB10',rx:'PB11'};}if(u.number===6)return{tx:['PC6','PA11'].find(p=>this.af(p,8)),rx:['PC7','PA12'].find(p=>this.af(p,8))};return super.pins(u);}
 af(pin,af){if(!pin||!this.r.board.gpio.includes(pin))return false;const bank=pin.charCodeAt(1)-65,n=+pin.slice(2),base=0x40020000+bank*1024;return !!(this.r.regs.get(0x40023830)&(1<<bank))&&((this.r.regs.get(base)>>>n*2)&3)===2&&((this.r.regs.get(base+32+(n>=8?4:0))>>>((n%8)*4))&15)===af;}
 mapped(pin,tx){if(this.r.board.cpu==='cortex-m4f'&&['PC6','PC7','PA11','PA12'].includes(pin))return this.af(pin,8);return super.mapped(pin,tx);}
 flowPins(u){return u.number===1?{cts:'PA11',rts:'PA12'}:u.number===2?{cts:'PA0',rts:'PA1'}:u.number===3?{cts:'PB13',rts:'PB14'}:{cts:'PG13',rts:'PG8'};}
 cts(u){const cr3=this.cr(u,20);if(!(cr3&512))return true;const pin=this.flowPins(u).cts;if(!this.r.board.gpio.includes(pin))return false;return this.r.inputs[pin]===false;}
 pins(u){const p=this.normalPins(u);return p&&this.cr(u,20)&(8|32)?{...p,rx:p.tx}:p;}
 format(u,receive=true){const special=this.cr(u,20)&(8|32);if(!special)return super.format(u,receive);if(!this.enabled(u,receive?4:8)||receive&&this.cr(u,20)&8&&this.enabled(u,8))return null;const cr=this.cr(u),brr=this.cr(u,8)&65535,over8=!!(cr&32768),divisor=over8?(brr>>>4)*8+(brr&7):brr,stop=(this.cr(u,16)>>>12)&3,parity=cr&1024?(cr&512?'odd':'even'):null;if(!divisor||!this.physical(u))return null;return{period:divisor*this.divider(u),bits:(cr&4096?9:8)-(parity?1:0),stops:[1,.5,2,1.5][stop],receiveStops:stop===1?.5:1,allow9:true,parity};}
 readLine(u){if(this.cr(u,20)&2){if(!this.format(u))return null;return this.r.count>=(u.irReceiveUntil??-Infinity);}return super.readLine(u);}
 clockPin(u){return {1:'PA8',2:'PA4',3:'PB12',6:'PC8'}[u.number];}
 pump(u){if(!this.cts(u))return;const cr2=this.cr(u,16),cr3=this.cr(u,20);if(!(cr2&2048)&&!(cr3&0x2a))return super.pump(u);if(u.shift!==null||u.tdr===null||!this.enabled(u,8))return;const f=this.format(u,false);if(!f)return;const value=u.tdr&((1<<f.bits)-1),irda=!!(cr3&2),smart=!!(cr3&32),bits=[false];let ones=0;for(let i=0;i<f.bits;i++){bits.push(!!(value&(1<<i)));ones+=(value>>i)&1;}if(f.parity)bits.push(f.parity==='odd'?!(ones%2):!!(ones%2));u.shift=value;u.tdr=null;u.sr=(u.sr|128)&~64;u.high=irda?true:false;u.ck=!!(cr2&1024);this.changed=true;const pulse=cr3&4?Math.max(1,(this.cr(u,24)&255)*this.divider(u)):f.period*3/16;
 for(let i=0;i<bits.length;i++){if(irda){this.schedule(u,i*f.period,()=>{u.high=!bits[i];this.changed=true;});if(!bits[i])this.schedule(u,i*f.period+pulse,()=>{u.high=false;this.changed=true;});}else if(i)this.schedule(u,i*f.period,()=>{u.high=bits[i];this.changed=true;});}
 if(cr2&2048&&!smart)for(let i=0;i<f.bits-(cr2&256?0:1);i++){const at=(i+1+(cr2&512?.5:0))*f.period;this.schedule(u,at,()=>{u.ck=!(cr2&1024);this.changed=true;});this.schedule(u,at+f.period/2,()=>{u.ck=!!(cr2&1024);this.changed=true;});}
 const stop=bits.length;this.schedule(u,stop*f.period,()=>{u.high=!irda;this.changed=true;});const guard=smart?(this.cr(u,24)>>>8)&255:0;this.schedule(u,(stop+f.stops+guard)*f.period,()=>{u.shift=null;u.sr|=64;if(this.terminal(u))this.r.serial+=String.fromCharCode(value&255);this.pump(u);});}
 receive(u,frame){super.receive(u,frame);if(frame.error==='parity'&&(this.cr(u,20)&48)===48){u.nackUntil=this.r.count+(frame.format?.period||1);this.changed=true;}}
 tick(){super.tick();for(const u of this.units){if(this.enabled(u)&&this.cr(u,20)&32){const div=(this.cr(u,24)&255)||1,level=!!(Math.floor(this.r.count/(div*this.divider(u)))&1);if(level!==u.smartClock){u.smartClock=level;this.changed=true;}}if(u.nackUntil&&this.r.count>=u.nackUntil){u.nackUntil=0;this.changed=true;}}}

 observe(){for(const u of this.units)if(this.cr(u,20)&2){const p=this.pins(u),v=this.r.inputVoltages?.[p?.rx],high=Number.isFinite(v)?v>=2.31:!!this.r.inputs[p?.rx];if(high&&u.irPrevious!==true)u.irReceiveUntil=this.r.count+(this.format(u)?.period||1);u.irPrevious=high;}super.observe();for(const u of this.units){const cts=this.cts(u);if(u.lastCTS!==undefined&&u.lastCTS!==cts)u.sr|=512;u.lastCTS=cts;if(cts)this.pump(u);if(this.cr(u,16)&16384){const low=this.readLine(u)===false,format=this.format(u),period=format?.period||Infinity;if(low){u.breakAt??=this.r.count;if(this.r.count-u.breakAt>=period*((this.cr(u,16)&32)?11:10))u.sr|=256;}else u.breakAt=null;}}}
 write(a,v,n=4){const u=this.find(a&~3);if(!u)return false;const off=(a&~3)-u.base;if(off===20){if(v&~0x7ff)throw Error('USART CR3 ayrılmış bitler.');if((v&2)&&(v&(8|32)))throw Error('USART IrDA ile half-duplex/smartcard birlikte seçilemez.');const old=this.cr(u,20);this.r.regs.set(u.base+20,v&0x7ff);if((old^v)&512)this.pump(u);return true;}return super.write(a,v,n);}
 pending(u){if(!this.enabled(u))return false;const cr=this.cr(u),cr2=this.cr(u,16),cr3=this.cr(u,20);let sr=u.sr;if(!this.physical(u)&&this.terminal(u)&&this.r.rx.length)sr|=32;return !!((sr&32)&&(cr&32)||(sr&128)&&(cr&128)||(sr&64)&&(cr&64)||(sr&8)&&(cr&32)||(sr&6)&&(cr3&1)||(sr&1)&&(cr&256)||(sr&256)&&(cr2&64)||(sr&512)&&(cr3&1024));}
 irqMask(){let mask=0;for(const u of this.units)if(u.number<=2&&this.pending(u))mask|=1<<(u.number-1);return mask;}
 irqExtra(){let mask=0;for(const u of this.units)if(u.number>2&&this.pending(u))mask|=1<<(u.number===3?27:28);return mask;}
 outputs(states){super.outputs(states);for(const u of this.units){const p=this.pins(u),cr3=this.cr(u,20),cr2=this.cr(u,16);if(p?.tx&&this.physical(u)){if(cr3&2&&this.enabled(u,8))states[p.tx]={high:u.shift===null?false:u.high,outputEnabled:true,voltage:u.shift===null?0:u.high?3.3:0,mode:'USART_IRDA'};if(cr3&(8|32)){const high=u.nackUntil?false:u.high,active=this.enabled(u,8)||!!u.nackUntil;states[p.tx]={high,outputEnabled:active&&!high,voltage:0,mode:'USART_OPEN_DRAIN'};}}const pin=this.clockPin(u),af=u.number===6?8:7,mapped=this.r.board.cpu==='cortex-m4f'?this.af(pin,af):super.mapped(pin,true);if(pin&&mapped&&this.enabled(u)&&((cr2&2048)||(cr3&32))){const div=(this.cr(u,24)&255)||1,high=cr3&32?!!(Math.floor(this.r.count/(div*this.divider(u)))&1):!!u.ck;states[pin]={high,outputEnabled:true,voltage:high?3.3:0,mode:'USART_CLOCK'};}}for(const u of this.units)if(this.enabled(u)&&this.cr(u,20)&256){const pin=this.flowPins(u).rts;if(!this.r.board.gpio.includes(pin))continue;const mapped=this.r.board.cpu==='cortex-m4f'?this.af(pin,7):super.mapped(pin,true);if(mapped){const high=!!(u.sr&32);states[pin]={high,outputEnabled:true,voltage:high?3.3:0,mode:'USART'+u.number+'_RTS'};}}return states;}
}
